```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <rpn-token>...\n", argv[0]);
        return EXIT_FAILURE;
    }

    /*
     * The maximum number of operands is at most the number of tokens.
     * Allocate enough stack space for all tokens.
     */
    size_t capacity = (size_t)(argc - 1);
    long long *stack = malloc(capacity * sizeof(*stack));
    if (stack == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    size_t top = 0;

    for (int i = 1; i < argc; ++i) {
        const char *token = argv[i];

        if (strcmp(token, "+") == 0 ||
            strcmp(token, "-") == 0 ||
            strcmp(token, "*") == 0 ||
            strcmp(token, "/") == 0) {

            if (top < 2) {
                fprintf(stderr, "Error: stack underflow at operator '%s'\n", token);
                free(stack);
                return EXIT_FAILURE;
            }

            long long rhs = stack[--top];
            long long lhs = stack[--top];
            long long result;

            if (strcmp(token, "+") == 0) {
                result = lhs + rhs;
            } else if (strcmp(token, "-") == 0) {
                result = lhs - rhs;
            } else if (strcmp(token, "*") == 0) {
                result = lhs * rhs;
            } else { /* "/" */
                if (rhs == 0) {
                    fprintf(stderr, "Error: division by zero\n");
                    free(stack);
                    return EXIT_FAILURE;
                }

                /* Avoid undefined behavior for LLONG_MIN / -1 */
                if (lhs == LLONG_MIN && rhs == -1) {
                    fprintf(stderr, "Error: integer overflow in division\n");
                    free(stack);
                    return EXIT_FAILURE;
                }

                result = lhs / rhs;
            }

            stack[top++] = result;
        } else {
            char *endptr;
            errno = 0;
            long long value = strtoll(token, &endptr, 10);

            if (endptr == token || *endptr != '\0') {
                fprintf(stderr, "Error: invalid token '%s'\n", token);
                free(stack);
                return EXIT_FAILURE;
            }

            if (errno == ERANGE) {
                fprintf(stderr, "Error: integer out of range in token '%s'\n", token);
                free(stack);
                return EXIT_FAILURE;
            }

            if (top == capacity) {
                fprintf(stderr, "Error: stack overflow\n");
                free(stack);
                return EXIT_FAILURE;
            }

            stack[top++] = value;
        }
    }

    if (top != 1) {
        fprintf(stderr,
                "Error: malformed expression: stack has %zu value%s at end\n",
                top, top == 1 ? "" : "s");
        free(stack);
        return EXIT_FAILURE;
    }

    printf("%lld\n", stack[0]);
    free(stack);
    return EXIT_SUCCESS;
}
```

